typedef struct {
    long timestamp;
    int status_code;
} DetailStruct;

typedef struct Config {
    unsigned int version;
    DetailStruct data_detail;
    char name[32];
} Config;

// C-style type deduction via common compiler extension (GCC/Clang)
// Casts 0 to struct pointer, accesses member M, and deduces its type.
#define DEDUCE_TYPE(StructType, Member) \
    __typeof__(((StructType*)0)->Member)

// Usage: Deduce type of nested member 'data_detail'
DEDUCE_TYPE(Config, data_detail) detail_local;

// Usage: Deduce primitive type 'version'
DEDUCE_TYPE(Config, version) version_local;

// detail_local is now of type DetailStruct
// version_local is now of type unsigned int
